import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十二卦 恒 雷风恒 震上巽下","description":"周易 - 第三十二卦 恒 雷风恒 震上巽下","frontmatter":{"title":"第三十二卦 恒 雷风恒 震上巽下","description":"周易 - 第三十二卦 恒 雷风恒 震上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/033.md","filePath":"zh/classics/zhouyi/033.md"}'),l={name:"zh/classics/zhouyi/033.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="恒" tabindex="-1">恒 <a class="header-anchor" href="#恒" aria-label="Permalink to “恒”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，无咎，利贞，利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒亨无咎，利贞；久於其道也，天地之道，恒久而不已也。利有攸往，终则有始也。日月得天，而能久照，四 时变化，而能久成，圣人久於其道，而天下化成；观其所恒，而天地万物之情可见矣！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷风，恒；君子以立不易方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>浚恒，贞凶，无攸利。象曰：浚恒之凶，始 求深也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>悔亡。象曰：九二悔亡，能久中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>不恒其德，或承之羞，贞吝。象曰：不恒其德，无所容也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>田无禽。象曰：久非其位，安得禽也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>恒其德，贞，妇人吉，夫子凶。象曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>振恒，凶。象曰：振恒在上，大无功也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
